#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn capabilities() -> SessionCapabilities {
        SessionCapabilities {
            terminal: true,
            resize: true,
            flow_control: true,
            interrupt: true,
            output_cursor: true,
            remote_files: true,
            port_forwarding: true,
        }
    }

    #[test]
    fn serializes_status_event_with_camel_case_contract() {
        let event = SessionEvent::Status(SessionStatusEvent {
            session: ManagedSession {
                id: "session-1".into(),
                target_id: "target-1".into(),
                title: "PowerShell".into(),
                status: SessionLifecycleStatus::Running,
                capabilities: capabilities(),
                error: None,
            },
        });
        let value = serde_json::to_value(event).expect("serialize status event");
        assert_eq!(value["type"], "status");
        assert_eq!(value["payload"]["session"]["targetId"], "target-1");
        assert_eq!(value["payload"]["session"]["status"], "running");
    }

    #[test]
    fn output_cursor_counts_utf8_bytes() {
        let output = SessionOutputEvent::new("session-1", 7, "A中");
        assert_eq!(SESSION_CURSOR_UNIT, "utf8Bytes");
        assert_eq!(SESSION_MAX_CURSOR, 9_007_199_254_740_991);
        assert_eq!(output.start_cursor, 7);
        assert_eq!(output.end_cursor, 11);
        let capped = SessionOutputEvent::new("session-1", u64::MAX, "abc");
        assert_eq!(capped.start_cursor, SESSION_MAX_CURSOR);
        assert_eq!(capped.end_cursor, SESSION_MAX_CURSOR);
    }

    #[test]
    fn serializes_exit_event_with_optional_process_details() {
        let event = SessionEvent::Exit(SessionExitEvent {
            session_id: "session-1".into(),
            reason: SessionExitReason::Exited,
            cursor: 42,
            exit_code: Some(0),
            signal: None,
            message: None,
        });
        assert_eq!(
            serde_json::to_value(event).expect("serialize exit event"),
            json!({
                "type": "exit",
                "payload": {
                    "sessionId": "session-1",
                    "reason": "exited",
                    "cursor": 42,
                    "exitCode": 0
                }
            })
        );
    }
}
